/** IDs that are available from the start and do not need to be purchased. */
export function getDefaultOwnedCosmeticIds(target = 'pet', catalog = COSMETIC_CATALOG) {
  return (Array.isArray(catalog) ? catalog : [])
    .filter((item) => item && item.defaultUnlocked === true
      && (item.target === target || item.target === 'both' || !item.target))
    .map((item) => item.id);
}

const CATEGORY_SLOTS = {
  pet: {
    hats: 'headwear',
    accessories: 'accessory',
    clothes: 'outfit',
    eyes: 'eyes',
    corak: 'pattern',
  },
  avatar: {
    hats: 'hair',
    accessories: 'accessory',
    clothes: 'outfit',
    eyes: 'eyes',
    corak: 'body',
  },
};

export function getCosmeticSlot(item, target = 'pet') {
  if (!item) return null;
  if (typeof item.slot === 'string' && item.slot.trim()) return item.slot.trim().toLowerCase();
  const category = String(item.category || '').trim().toLowerCase();
  return CATEGORY_SLOTS[target]?.[category] || CATEGORY_SLOTS.pet[category] || null;
}

export function getCosmeticAssetUrl(item) {
  if (!item) return null;
  const source = item.asset_url || item.asset || item.image_url || null;
  if (typeof source !== 'string' || !source.trim()) return null;
  const value = source.trim();
  if (/^(https?:|data:|blob:)/i.test(value) || value.startsWith('/wp-content/')) return value;
  if (value.startsWith('/')) return value;

  const relativePath = value.replace(/^\.\//, '').replace(/^cosmetics\//, '').replace(/^\/+/, '');
  const configuredBase = window.petgameConfig?.cosmeticsBaseUrl;
  const base = configuredBase || `${import.meta.env.BASE_URL}cosmetics/`;
  return `${base.replace(/\/?$/, '/')}${relativePath}`;
}

/** Merge the editable local catalog over server/demo items by stable ID. */
export function mergeCosmeticCatalog(items = [], catalog = COSMETIC_CATALOG) {
  const merged = new Map();
  [...(Array.isArray(items) ? items : []), ...(Array.isArray(catalog) ? catalog : [])].forEach((item) => {
    if (!item || typeof item.id !== 'string') return;
    const previous = merged.get(item.id) || {};
    merged.set(item.id, { ...previous, ...item });
  });
  return Array.from(merged.values());
}

export function getEquippedCosmeticItems(selections = {}, items = [], target = 'pet') {
  const ids = new Set(Object.values(selections || {}).filter(Boolean));
  return (Array.isArray(items) ? items : []).filter((item) => (
    ids.has(item.id)
    && (item.target === target || item.target === 'both' || !item.target)
    && Boolean(getCosmeticAssetUrl(item))
  ));
}
